const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const center = ee.Geometry.Point([45.203, 4.742]); // Beledweyne, Somalia
    const roi = center.buffer({distance: 30000}).bounds(); // ~30 km box

    const dataset = 'ECMWF/ERA5_LAND/HOURLY';
    const band = 'volumetric_soil_water_layer_1'; // 0-7 cm soil layer, m3/m3

    const periods = {
      y2017: {start: '2017-05-01', end: '2017-06-01'},
      y2018: {start: '2018-05-01', end: '2018-06-01'}
    };

    async function getPeriodStats(start, end) {
      let col = ee.ImageCollection(dataset).filterDate(start, end).select(band);
      let size = await col.size().getInfo();
      // Recovery attempt if empty: widen window by ±15 days
      if (size === 0) {
        const altStart = ee.Date(start).advance(-15, 'day').format('YYYY-MM-dd');
        const altEnd = ee.Date(end).advance(15, 'day').format('YYYY-MM-dd');
        const altStartStr = await altStart.getInfo();
        const altEndStr = await altEnd.getInfo();
        col = ee.ImageCollection(dataset).filterDate(altStartStr, altEndStr).select(band);
        size = await col.size().getInfo();
        if (size === 0) {
          return {size: 0, count: 0, mean: null, usedStart: altStartStr, usedEnd: altEndStr};
        }
        start = altStartStr; end = altEndStr;
      }
      const img = col.mean();
      const count = await img.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: 3000,
        maxPixels: 1e9,
        bestEffort: true
      }).get(band).getInfo();
      if (!count || count === 0) {
        return {size, count: 0, mean: null, usedStart: start, usedEnd: end};
      }
      const mean = await img.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: roi,
        scale: 3000,
        maxPixels: 1e9,
        bestEffort: true
      }).get(band).getInfo();
      return {size, count, mean, usedStart: start, usedEnd: end};
    }

    const s2017 = await getPeriodStats(periods.y2017.start, periods.y2017.end);
    const s2018 = await getPeriodStats(periods.y2018.start, periods.y2018.end);

    // Output concise evidence
    console.log('Region center (lon,lat): 45.203, 4.742; buffer_km: 30');
    console.log('Dataset: ERA5-Land hourly; Band: volumetric_soil_water_layer_1 (m3/m3)');
    console.log(`2017 May Images: ${s2017.size}`);
    console.log(`2018 May Images: ${s2018.size}`);

    // Case handling
    if (s2017.size === 0 || s2018.size === 0) {
      console.log('Empty collection for at least one period after recovery.');
      console.log('C1');
      return;
    }
    if (!s2017.count || !s2018.count) {
      console.log('No valid pixels after processing for at least one period.');
      console.log('C2');
      return;
    }
    if (s2017.mean == null || s2018.mean == null || isNaN(s2017.mean) || isNaN(s2018.mean)) {
      console.log('Calculation resulted in null/NaN.');
      console.log('C3');
      return;
    }
    // Validate plausible range [0,1] for volumetric soil moisture
    if (s2017.mean < 0 || s2017.mean > 1 || s2018.mean < 0 || s2018.mean > 1) {
      console.log('Invalid soil moisture range detected.');
      console.log('C3');
      return;
    }

    const m17 = s2017.mean;
    const m18 = s2018.mean;
    const change = m18 - m17;
    const pct = (m17 > 0) ? (100 * change / m17) : null;

    console.log(`2017 May Mean SM: ${m17.toFixed(4)} (pixels: ${s2017.count})`);
    console.log(`2018 May Mean SM: ${m18.toFixed(4)} (pixels: ${s2018.count})`);
    console.log(`Change (2018-2017): ${change.toFixed(4)}${pct !== null ? ` (${pct.toFixed(1)}%)` : ''}`);

    // Final answer
    const answer = (m18 > m17) ? 'A' : 'B';
    console.log(answer);
  } catch (err) {
    console.error('Error:', err.message || err);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
